#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <stdint.h>

template <typename T>
__device__ __forceinline__ float to_f(T x) { return static_cast<float>(x); }

template <typename scalar_t, typename trig_t>
__global__ void rope_contig_kernel(
    const scalar_t* __restrict__ q, scalar_t* __restrict__ qo,
    const scalar_t* __restrict__ k, scalar_t* __restrict__ ko,
    const trig_t* __restrict__ cos, const trig_t* __restrict__ sin,
    int sl, int cos_bs, int n_qh, int n_kh, int hd)
{
    extern __shared__ float smem[];
    const int hdh = hd >> 1;
    float* cbuf = smem;
    float* sbuf = smem + hdh;
    const int tid = threadIdx.x;
    const int row = blockIdx.x;
    const int b = row / sl;
    const int s = row - b * sl;
    const int cbrow = ((cos_bs == 1 ? 0 : b) * sl + s) * hdh;
    for (int d = tid; d < hdh; d += blockDim.x) {
        cbuf[d] = to_f(cos[cbrow + d]);
        sbuf[d] = to_f(sin[cbrow + d]);
    }
    __syncthreads();
    int64_t qbase_row = (int64_t)row * n_qh * hd;
    #pragma unroll 1
    for (int h = 0; h < n_qh; ++h) {
        int64_t base = qbase_row + (int64_t)h * hd;
        for (int d = tid; d < hdh; d += blockDim.x) {
            float x1 = to_f(q[base + d]);
            float x2 = to_f(q[base + d + hdh]);
            float c = cbuf[d], sn = sbuf[d];
            qo[base + d] = static_cast<scalar_t>(x1 * c - x2 * sn);
            qo[base + d + hdh] = static_cast<scalar_t>(x2 * c + x1 * sn);
        }
    }
    int64_t kbase_row = (int64_t)row * n_kh * hd;
    #pragma unroll 1
    for (int h = 0; h < n_kh; ++h) {
        int64_t base = kbase_row + (int64_t)h * hd;
        for (int d = tid; d < hdh; d += blockDim.x) {
            float x1 = to_f(k[base + d]);
            float x2 = to_f(k[base + d + hdh]);
            float c = cbuf[d], sn = sbuf[d];
            ko[base + d] = static_cast<scalar_t>(x1 * c - x2 * sn);
            ko[base + d + hdh] = static_cast<scalar_t>(x2 * c + x1 * sn);
        }
    }
    if (hd & 1) {
        for (int h = tid; h < n_qh; h += blockDim.x) qo[qbase_row + (int64_t)h * hd + hd - 1] = q[qbase_row + (int64_t)h * hd + hd - 1];
        for (int h = tid; h < n_kh; h += blockDim.x) ko[kbase_row + (int64_t)h * hd + hd - 1] = k[kbase_row + (int64_t)h * hd + hd - 1];
    }
}

