    int64_t ko_s0, int64_t ko_s1, int64_t ko_s2, int64_t ko_s3,
    int64_t cos_s0, int64_t cos_s1, int64_t cos_s2,
    int64_t sin_s0, int64_t sin_s1, int64_t sin_s2)
{
